func readinessClass(readiness string) string {
	switch readiness {
	case "complete":
		return "badge-success"
	case "video_ready", "endpoint_ready":
		return "badge-info"
	case "concept_ready", "blocking_ready":
		return "badge-warning"
	default:
		return "badge-ghost"
	}
}

func itoaT(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

